package dev.mesbase;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.context.TestConfiguration;import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.context.DynamicPropertySource;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.core.env.Environment;
import java.net.*;import java.net.http.*;import java.util.*;
import dev.MesBaseApplication;import dev.mesbase.core.factory.*;import dev.mesbase.infrastructure.catalog.*;import dev.mesbase.platform.management.*;import dev.mesbase.platform.management.PlatformContracts.*;import dev.mesbase.infrastructure.platform.PlatformRows.*;
/** TEST ONLY actual HTTP + DB-backed identity/grants + new error model. Isolated embedded Tomcat/H2. */
@SpringBootTest(classes={MesBaseApplication.class,PlatformHttpTest.Fixture.class},
 webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"mes.runtime.enabled=false"})
class PlatformHttpTest {
 @DynamicPropertySource static void properties(DynamicPropertyRegistry p){p.add("spring.datasource.druid.filters",()->"stat");p.add("mes.legacy-test-only",()->"true");p.add("mes.system.enabled",()->"false");p.add("mes.platform.enabled",()->"true");p.add("mes.platform.url",()->"jdbc:h2:mem:platform-http-test-"+UUID.randomUUID()+";DB_CLOSE_DELAY=-1");p.add("mes.platform.username",()->"sa");p.add("mes.platform.password",()->"");p.add("mes.platform.migrate",()->"true");p.add("mes.platform.file-root",()->System.getProperty("java.io.tmpdir")+"/mes-platform-http-test-files-"+UUID.randomUUID());}
 @TestConfiguration static class Fixture {
  @Bean @Primary FactoryCatalog factories(){return new InMemoryFactoryCatalog(List.of(new Factory(new FactoryId("A"),"TEST","A","TEST ONLY A",FactoryStatus.ENABLED),new Factory(new FactoryId("B"),"TEST","B","TEST ONLY B",FactoryStatus.ENABLED)));}
  @Bean org.springframework.beans.factory.SmartInitializingSingleton seed(PlatformService s){return ()->{var credential=new PasswordInput("TEST-ONLY-http-password");var visitor=s.createUser(new NewUser(new UserInput("visitor","TEST ONLY no role",Status.ENABLED),credential));var reader=s.createUser(new NewUser(new UserInput("reader","TEST ONLY reader",Status.ENABLED),credential));s.createUser(new NewUser(new UserInput("disabled","TEST ONLY disabled",Status.DISABLED),credential));var r=s.saveRole(null,new RoleInput("TEST ONLY A role",RoleKind.FACTORY,"A",Status.ENABLED));var menu=s.saveMenu(null,new MenuInput(null,"TEST ONLY Factory access","/foundation","foundation:access:read",0,MenuKind.MENU));s.roleMenus(r.id(),new Links(List.of(menu.id())));s.userRoles(reader.id(),new Links(List.of(r.id())));var admin=s.createUser(new NewUser(new UserInput("admin","TEST ONLY platform admin",Status.ENABLED),credential));var ar=s.saveRole(null,new RoleInput("TEST ONLY platform",RoleKind.PLATFORM,null,Status.ENABLED));var pm=s.saveMenu(null,new MenuInput(null,"TEST ONLY users","/platform/users","platform:users:read",0,MenuKind.MENU));s.roleMenus(ar.id(),new Links(List.of(pm.id())));s.userRoles(admin.id(),new Links(List.of(ar.id())));};}
 }
 @Autowired Environment env;@Autowired PlatformService service;private final HttpClient client=HttpClient.newHttpClient();
 HttpResponse<String> req(String method,String path,String token,String factory,String body)throws Exception{var builder=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+env.getProperty("local.server.port")+path)).timeout(java.time.Duration.ofSeconds(10));if(token!=null)builder.header("Authorization","Bearer "+token);if(factory!=null)builder.header("X-Factory-Id",factory);if(body!=null)builder.header("Content-Type","application/json");return client.send(builder.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
 String login(String username)throws Exception{var response=req("POST","/api/platform/session",null,null,"{\"username\":\""+username+"\",\"password\":\"TEST-ONLY-http-password\"}");assertEquals(200,response.statusCode(),response.body());return new tools.jackson.databind.json.JsonMapper().readTree(response.body()).get("accessToken").asText();}
 @Test void validWrongDisabledAndEmptyRoleAuthentication()throws Exception{var token=login("visitor");assertEquals(200,req("GET","/api/platform/me",token,null,null).statusCode());assertEquals(200,req("GET","/api/foundation/context",token,"A",null).statusCode());assertEquals(200,req("GET","/api/foundation/context",token,"B",null).statusCode());assertEquals(403,req("GET","/api/foundation/access",token,"A",null).statusCode());assertEquals(401,req("POST","/api/platform/session",null,null,"{\"username\":\"visitor\",\"password\":\"wrong\"}").statusCode());assertEquals(401,req("POST","/api/platform/session",null,null,"{\"username\":\"disabled\",\"password\":\"TEST-ONLY-http-password\"}").statusCode());}
 @Test void factoryGrantAndMenuAreRequestScoped()throws Exception{var token=login("reader");assertEquals(200,req("GET","/api/foundation/access",token,"A",null).statusCode());assertEquals(403,req("GET","/api/foundation/access",token,"B",null).statusCode());assertTrue(req("GET","/api/platform/navigation",token,"A",null).body().contains("foundation:access:read"));assertFalse(req("GET","/api/platform/navigation",token,"B",null).body().contains("foundation:access:read"));assertEquals(403,req("GET","/api/platform/users",token,"A",null).statusCode());}
 @Test void platformGrantWorksWithoutFactoryAndDoesNotGrantBusiness()throws Exception{var token=login("admin");var users=req("GET","/api/platform/users?offset=0&limit=20",token,null,null);assertEquals(200,users.statusCode(),users.body());assertTrue(users.body().contains("\"items\""));assertTrue(users.body().contains("\"total\""));assertFalse(users.body().contains("passwordHash"));assertFalse(users.body().contains("TEST-ONLY-http-password"));assertEquals(403,req("GET","/api/foundation/access",token,"A",null).statusCode());assertEquals(403,req("POST","/api/platform/users",token,null,"{}").statusCode());}
 @Test void logoutRevokesAndInvalidBearerUsesSafe401()throws Exception{var token=login("visitor");assertEquals(204,req("DELETE","/api/platform/session",token,null,null).statusCode());var rejected=req("GET","/api/platform/me",token,null,null);assertEquals(401,rejected.statusCode(),rejected.body());assertTrue(rejected.body().contains("UNAUTHENTICATED"));assertTrue(rejected.body().contains("requestId"));assertEquals(401,req("GET","/api/platform/me","invalid",null,null).statusCode());}
 @Test void inputFailuresReturnReal400AndDoNotEchoCredentials()throws Exception{var response=req("POST","/api/platform/session",null,null,"{\"username\":\"visitor\",\"password\":\"TEST-ONLY-secret-value\",\"factoryId\":\"A\"}");assertEquals(400,response.statusCode(),response.body());assertFalse(response.body().contains("secret-value"));assertTrue(response.body().contains("BAD_REQUEST"));}
 @Test void operationsAreAuditedWithServerIdActorAndScope()throws Exception{var token=login("admin");var response=req("GET","/api/platform/users",token,"A",null);String id=response.headers().firstValue("X-Request-Id").orElseThrow();assertTrue(service.audits(0,100).stream().anyMatch(a->a.requestId().equals(id)&&a.factoryId().equals("A")&&a.executionScope()==JobScope.PLATFORM));}
}
